from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by their LCS length with s.

    The result has n+1 entries and is computed modulo 998244353.
    Constraints: 1 <= n <= 10, 1 <= m <= 100, len(s) == n.
    """
    mod = 998244353

    # A bit records an increase between adjacent entries of the LCS row
    # for prefixes of s. Thus every possible row fits in an n-bit mask.
    letter_masks = {}
    for i, char in enumerate(s):
        letter_masks[char] = letter_masks.get(char, 0) | (1 << i)

    size = 1 << n
    transitions = []
    for state in range(size):
        counts = {state: 26 - len(letter_masks)}
        for matches in letter_masks.values():
            # Bit-parallel form of one ordinary LCS dynamic-programming row.
            x = state | matches
            next_state = x & ~(x - ((state << 1) | 1))
            counts[next_state] = counts.get(next_state, 0) + 1
        transitions.append(list(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following = [0] * size
        for state, count in enumerate(dp):
            if count:
                for next_state, multiplicity in transitions[state]:
                    following[next_state] += count * multiplicity
        dp = [count % mod for count in following]

    answer = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        answer[length] = (answer[length] + count) % mod
    return answer

