def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions, and replacements can turn
    s into t using at most k operations.

    The strings may have up to 500000 characters and k is at most 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if max(n, m) <= k:
        return True

    # A diagonal is i - j. Keep only the furthest source position on each
    # diagonal, extending every state through all immediately matching letters.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    if i == n and i == m:
        return True
    frontier = {0: i}

    for _ in range(k):
        next_frontier = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n:
                # Delete s[i].
                new_diagonal = diagonal + 1
                if i + 1 > next_frontier.get(new_diagonal, -1):
                    next_frontier[new_diagonal] = i + 1
            if j < m:
                # Insert t[j].
                new_diagonal = diagonal - 1
                if i > next_frontier.get(new_diagonal, -1):
                    next_frontier[new_diagonal] = i
            if i < n and j < m:
                # Replace s[i] with t[j].
                if i + 1 > next_frontier.get(diagonal, -1):
                    next_frontier[diagonal] = i + 1

        for diagonal, i in next_frontier.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            next_frontier[diagonal] = i
        frontier = next_frontier

    return False

